import { particles } from 'wgpu-kit/particles';
const canvas = document.querySelector<HTMLCanvasElement>('#canvas')!;
const sim = await particles({ count: 4096, mode: 'grid', seed: 'example' });
await sim.attach(canvas);
let raf = 0;
let stopped = false;
function frame() {
  if (stopped) return;
  sim.tick();
  raf = requestAnimationFrame(frame);
}
raf = requestAnimationFrame(frame);
function dispose() {
  stopped = true;
  cancelAnimationFrame(raf);
  sim.destroy();
}

sim.tick();
const { pos, vel, species } = sim.buffers();
const positions = await pos.read();
console.log(positions);
